  async function loadCloudOrders(){const {data:rows,error}=await supabaseClient.from("orders").select("order_number,customer_name,contact,items_text,total,status,created_at").order("created_at",{ascending:false});if(error)throw error;data.orders=(rows||[]).map(r=>({id:r.order_number,name:r.customer_name,contact:r.contact,itemsText:r.items_text,total:Number(r.total),status:r.status,createdAt:r.created_at}));save();}
  async function saveCloudOrder(o){const row={order_number:o.id,customer_name:o.name,contact:o.contact||"",items_text:o.itemsText||"",total:Number(o.total||0),status:o.status,created_at:o.createdAt||new Date().toISOString()};const [order,tracking]=await Promise.all([supabaseClient.from("orders").upsert(row),supabaseClient.from("order_tracking").upsert({order_number:o.id,status:o.status,created_at:row.created_at})]);if(order.error)throw order.error;if(tracking.error)throw tracking.error;}
  async function loadCloudTracking(orderId){const {data:row,error}=await supabaseClient.from("order_tracking").select("order_number,status,created_at").eq("order_number",orderId).maybeSingle();if(error)throw error;return row?{id:row.order_number,status:row.status,createdAt:row.created_at}:null;}
