    const categoryPanel="<section class='admin-panel'><div class='panel-head'><div><h3>Categories</h3><p>Create categories and choose whether customers can shop them or see “Coming soon”.</p></div></div><form class='cms-card cms-form cms-create-form' data-cms-form='category'><div class='form-columns'><label>New category<input name='name' required placeholder='e.g. Sarees'></label><label>URL slug<input name='slug' placeholder='sarees'></label></div><div class='form-columns'><label>Availability<select name='status'><option value='live'>Live</option><option value='coming_soon'>Coming soon</option></select></label><label>Image URL<input name='image' placeholder='Optional image URL'></label></div><label>Upload category image<input name='imageFile' type='file' accept='image/*'></label><button class='button button-dark'>＋ Add category</button></form><div class='cms-card-list'>"+(categoryRows||"<p class='empty-state'>Add your first category.</p>")+"</div></section>";
